//! The UI as data. A `Ui` is everything on screen: a tree of nodes, the data sources the tree
//! binds to, and the keys. It is plain JSON, so a whole UI can be written by hand, generated by
//! an agent, pushed into a running screen and read back out.
//!
//! The world (your notes, prices, logs) is not in here. A node names a source (`bind`), a source
//! says how to fetch the world (a command that prints JSON, or a literal value), and the view
//! reads whatever the runtime last fetched.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeMap;

/// One whole UI.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Ui {
    pub root: Node,
    /// Named data sources, fetched by the runtime and bound to by nodes.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub data: BTreeMap<String, Source>,
    /// Starting values for store entries (`seed`s): each is written only when its entry doesn't
    /// exist yet, so a push never overwrites what the person or another agent wrote.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub store: BTreeMap<String, Value>,
    /// Keys that work everywhere (a focused node's own `keys` win).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub keys: BTreeMap<String, Action>,
    /// Named colours every node can use, and the screen's own (`bg`, `fg`, `border`, `accent`,
    /// `pos`, `neg`, `hover`).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub theme: BTreeMap<String, String>,
    /// Callouts, arrows, rings and spotlights over the screen, anchored to nodes and rows
    /// (placed by caretline-layers).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub layers: Vec<LayerSpec>,
    /// Where the focus goes when this UI is pushed (a node id), instead of staying where it was
    /// or going to the first node that takes it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub focus: Option<String>,
    /// The runtime's own status line: the status, else the first problem, else hints. `false`
    /// hides it, so the UI owns every row; `"speed"` adds the speed meter (frames, build time,
    /// messages a second), which is bindable as `$stats` either way.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status_bar: Option<StatusBar>,
}

/// `status_bar`: shown or not, or shown with the speed meter.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum StatusBar {
    On(bool),
    Speed,
}

impl Serialize for StatusBar {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            StatusBar::On(b) => s.serialize_bool(*b),
            StatusBar::Speed => s.serialize_str("speed"),
        }
    }
}

impl StatusBar {
    pub fn shown(self) -> bool {
        self != StatusBar::On(false)
    }
}

impl<'de> Deserialize<'de> for StatusBar {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        match Value::deserialize(d)? {
            Value::Bool(b) => Ok(StatusBar::On(b)),
            Value::String(s) if s == "speed" => Ok(StatusBar::Speed),
            v => Err(wrong("status_bar is true, false or \"speed\"", &v)),
        }
    }
}

/// A theme: colour `tokens`, styles for the `parts` of components the runtime draws, named
/// `variants` a node can ask for, and the scales parts and styles name: `space` (`s2`),
/// `radius` (`r2`), `depth` (`e1`, shadows), `type` (roles: `body`, `display`) and `fonts`.
/// A part is a short ink (`accent+b`, as in template markup) or a whole style (see `Style`).
/// Themes are the person's or the project's, loaded with `--themes`; a push doesn't change them.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct ThemeSpec {
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub tokens: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub parts: BTreeMap<String, Part>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub variants: BTreeMap<String, Variant>,
    /// Spacing by name: `"s2": "8px"` (or cells, `1`).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub space: BTreeMap<String, Len>,
    /// Corner radii by name, in pixels: `"r2": 6`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub radius: BTreeMap<String, f32>,
    /// Elevations by name, each a list of shadows (a glow is a shadow with no offset).
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub depth: BTreeMap<String, Vec<Shadow>>,
    /// Type roles by name: `"display": {"font": "display", "size": 56, "weight": 800}`.
    #[serde(default, rename = "type", skip_serializing_if = "BTreeMap::is_empty")]
    pub types: BTreeMap<String, TypeRole>,
    /// Fonts by name: a family (`"Inter"`) or a font file (`"fonts/Anton.ttf"`). A type role's
    /// `font` names one, or a family directly.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub fonts: BTreeMap<String, String>,
    /// Reserved for transitions (phase 3): read, kept, not used yet.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub motion: BTreeMap<String, Value>,
}

/// A theme part: a short ink (`"accent+b"`) or a whole style.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Part {
    Ink(String),
    Whole(Box<Style>),
}

impl Part {
    /// The part's ink as a spec: itself, or a whole style's colours and modifiers
    /// (`fg+on-panel+b`), for what reads parts as ink.
    pub fn spec(&self) -> String {
        match self {
            Part::Ink(s) => s.clone(),
            Part::Whole(s) => s.spec(),
        }
    }
}

/// A length: cells (`1`), pixels (`"8px"`), or the name of a `space` entry (`"s2"`).
#[derive(Clone, Debug, PartialEq)]
pub enum Len {
    Cells(f32),
    Spec(String),
}

// Whole cells as integers, as they were written.
impl Serialize for Len {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            Len::Cells(n) if n.fract() == 0. && n.abs() < 1e9 => s.serialize_i64(*n as i64),
            Len::Cells(n) => s.serialize_f32(*n),
            Len::Spec(t) => s.serialize_str(t),
        }
    }
}

/// One shadow: offset, blur and spread in pixels, and its colour (a token or a colour, with
/// an optional alpha `0`–`1`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Shadow {
    #[serde(default)]
    pub x: f32,
    #[serde(default)]
    pub y: f32,
    #[serde(default)]
    pub blur: f32,
    #[serde(default)]
    pub spread: f32,
    pub color: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub alpha: Option<f32>,
}

/// A type role: a font (a `fonts` name or a family), size and line height in pixels, a weight
/// (100–900), letter spacing in pixels, and whether numbers are tabular.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct TypeRole {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub font: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub weight: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub line: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tracking: Option<f32>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub tabular: bool,
}

/// A background: a colour, or a gradient between two at an angle (degrees, 180 is top to
/// bottom).
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Fill {
    Colour(String),
    Gradient {
        from: String,
        to: String,
        #[serde(default = "down")]
        angle: f32,
    },
}

fn down() -> f32 {
    180.
}

impl Fill {
    /// The colour, or where a gradient starts.
    pub fn colour(&self) -> &str {
        match self {
            Fill::Colour(c) => c,
            Fill::Gradient { from, .. } => from,
        }
    }
}

/// A line around a box: its width in pixels, colour, and `solid` (the default), `dashed` or
/// `double`.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Line {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<String>,
}

/// A focus ring: a line `offset` pixels outside the box.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Ring {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub offset: Option<f32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
}

/// A named look: a style under the node's own, and a border and backdrop when the node has none.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Variant {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<Style>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub border: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub backdrop: Option<Backdrop>,
    /// The style of the node's title.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
}

/// One layer, anchored to a node (`on`) or one of its rows (`row`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct LayerSpec {
    pub on: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub row: Option<usize>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    /// Fill `title` and `text` from this source (`"fin.kpi"`), so a callout shows live values.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bind: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub arrow: bool,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub ring: bool,
    /// The ring pulses with this period (ms).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pulse: Option<u32>,
    /// Dim everything but the anchor and the box.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub spotlight: bool,
    /// Sides to try, in order: `below`, `above`, `right`, `left`.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub place: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub look: Option<Look>,
    /// Who placed it; drawn in the border (`◆ analyst`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub by: Option<String>,
    /// Shown only while this holds, as a node's `when`: a hint that goes once it's been taken.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub when: Option<String>,
}

/// How a layer looks: colours by name or `#rrggbb`, and the border.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Look {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub accent: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fill: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fg: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ring: Option<String>,
    /// `rounded` (default), `double`, `thick` or `plain`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<String>,
}

/// A node: what it is (`type` and its fields) plus the parts every node shares.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Node {
    /// Stable identity. A node with an id keeps its selection and scroll across pushes, can be
    /// focused (lists, tables) and can be replaced alone (`patch`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    /// Its share of the parent row/col: `12` (cells), `"48px"`, `"30%"`, `"*"` (the default) or
    /// `"2*"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size: Option<Size>,
    /// A title draws a border with it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub border: bool,
    /// The border: `rounded` (default), `double`, `thick` or `plain`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub edge: Option<String>,
    /// `left` (default), `center` or `right`, for text and big numbers.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub align: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<Style>,
    /// A callout that follows the mouse over this node's rows, filled from the hovered row.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tip: Option<Tip>,
    /// What a click does (after focusing the node and selecting the clicked row).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub click: Option<Action>,
    /// A pixel panel behind the node (rounded, shadowed), where the terminal draws images; a plain
    /// border where it doesn't.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub backdrop: Option<Backdrop>,
    /// Text drawn this many times larger (kitty's text sizing, OSC 66), where the terminal can.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scale: Option<u8>,
    /// The data source this node reads (a key of `Ui::data`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bind: Option<String>,
    /// Keys that work while this node has focus.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub keys: BTreeMap<String, Action>,
    /// A named look from the active theme's `variants` (its style, border and backdrop).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub variant: Option<String>,
    /// A meaning for the text colour, as a theme token: `warn`, `neg`, `accent`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tone: Option<String>,
    /// Space inside the node's border, over its style's: one length for every side, `[x, y]`, or
    /// `[top, right, bottom, left]`. A length is cells (`1`), pixels (`"8px"`) or a `space` name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pad: Option<Lens>,
    /// Space outside it, between it and what's beside it: lengths as `pad`'s.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub margin: Option<Lens>,
    /// Shown only while this holds: a bind that's set (`"dialog"`; not empty, false, 0 or null),
    /// not set (`"!dialog"`), or compared with a value (`"mode=edit"`, `"$screen.width>=120"`;
    /// `=`, `!=`, `<`, `<=`, `>`, `>=`); several joined by ` & ` must all hold. A hidden node
    /// takes no room and no focus.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub when: Option<String>,
    /// In a `stack`: where the node floats over the ones before it, instead of filling it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub float: Option<Float>,
    /// While shown, focus stays inside this node and what's behind it dims: a dialog.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub modal: bool,
    /// Bounds on the node's share of its row or column, as lengths: `"size": "60%", "max": "720px"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min: Option<Len>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max: Option<Len>,
    #[serde(flatten)]
    pub kind: Kind,
}

/// Where a floating node sits in its stack: `width` and `height` (cells, `"50%"`, `"240px"`; default the
/// whole stack) and `at` (`center`, the default, or `top`, `bottom`, `left`, `right` and the
/// corners, `top-right`), `margin` in from the edges (lengths as a node's `pad`).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Float {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<Size>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub height: Option<Size>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub at: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub margin: Option<Lens>,
}

impl Default for Node {
    fn default() -> Self {
        Node {
            id: None,
            size: None,
            title: None,
            border: false,
            style: None,
            bind: None,
            keys: BTreeMap::new(),
            edge: None,
            align: None,
            tip: None,
            click: None,
            backdrop: None,
            scale: None,
            variant: None,
            tone: None,
            pad: None,
            margin: None,
            when: None,
            float: None,
            modal: false,
            min: None,
            max: None,
            kind: Kind::Text { text: String::new(), wrap: None, lines: None },
        }
    }
}

/// The closed set of components. Layouts arrange these; they don't add new ones.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
pub enum Kind {
    /// Children stacked top to bottom, `gap` apart (a length, or `[x, y]`).
    Col {
        children: Vec<Node>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
    },
    /// Children side by side, `gap` apart (a length, or `[x, y]`).
    Row {
        children: Vec<Node>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
    },
    /// Children over each other, the last on top: each fills the stack, or floats where its
    /// `float` says (a dialog, a popup, a corner badge). With `when`, a layer comes and goes.
    Stack { children: Vec<Node> },
    /// A labelled control: Enter or Space while focused, or a click, runs its `click`.
    Button { label: String },
    /// The `template` node once for each item of the bound array, top to bottom (side by side
    /// with `row`), `gap` apart. In the template, `{$item}` and `{$item.path}` are filled from the
    /// item (ids, binds, `doc`, `size`: `"id": "panel-{$item.id}"`); every other placeholder is
    /// left for the node itself. An instance's share is its `size`, else an equal one.
    Each {
        template: Box<Node>,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        row: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        gap: Option<Gap>,
    },
    /// Where toasts show, newest first, a line each, instead of the screen's corner (a bar of
    /// the UI's own). Each takes the theme part `toast.<tone>`, else `toast`.
    Toasts {},
    /// A turning glyph before `text` (a template): something is under way. A bound source that
    /// hasn't arrived shows one too.
    Spinner {
        #[serde(default, skip_serializing_if = "String::is_empty")]
        text: String,
    },
    /// Text. `{field}` placeholders fill from the bound value (`{a.b}` reaches in). A line with
    /// no tab or fill wraps; `wrap: false` keeps each line on one, cut with `…` where it doesn't
    /// fit, and `lines` shows at most that many, the last ending in `…`.
    Text {
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        wrap: Option<bool>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        lines: Option<u16>,
    },
    /// A selectable list of `items`, or of the bound array, drawn as `Rows` say.
    List {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        #[serde(flatten)]
        rows: Rows,
    },
    /// An outline over the bound array (or `items`): each row's `nest` (default `children`) holds
    /// the rows under it. Rows fold and unfold (←/→, space); `open: false` starts them folded.
    /// Rows are drawn as `Rows` say, after their indent and a fold glyph (`▾`, `▸`, or `leaf`
    /// for a row with nothing under it, default `· `), and templates can read `{$depth}`,
    /// `{$kids}` (how many rows are under it) and `{$open}`. Store actions on the selected row
    /// reach it where it sits (`$ptr`, a JSON Pointer into the bound entry).
    Tree {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        nest: Option<String>,
        #[serde(default = "yes", skip_serializing_if = "Clone::clone")]
        open: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        leaf: Option<String>,
        #[serde(flatten)]
        rows: Rows,
    },
    /// A line filling the node: `glyph` (default `│` when taller than wide, else `─`).
    Rule {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        glyph: Option<String>,
    },
    /// A selectable table over the bound array (or `items`).
    Table {
        columns: Vec<Column>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        /// As a list's `filter`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        filter: Option<String>,
    },
    /// A sparkline over numbers: `values`, or `field` of each bound item.
    Sparkline {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        values: Vec<f64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        field: Option<String>,
    },
    /// Lines over shared axes. Each series reads numbers from a bind (and `field` of each item).
    Chart {
        series: Vec<Series>,
        /// Labels spread along the x axis.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        labels: Vec<String>,
    },
    /// Bars over the bound array (or `items`): `label` is a template, `value` a path. Negative
    /// values hang below a zero line.
    Bars {
        label: String,
        value: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        items: Vec<Value>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        width: Option<u16>,
        /// One row per item, the bar growing to the right, the label before it and the value
        /// after it, instead of columns.
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        horizontal: bool,
    },
    /// A filled bar: `value` (a template giving a number) out of `max` (default 1).
    Gauge {
        value: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        max: Option<f64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        label: Option<String>,
    },
    /// Large digits (a KPI): the filled template, in a 3-row block font.
    Big { text: String },
    /// A multi-line text editor (caretline) on a text entry in the store: `bind` names the
    /// entry (default: the editor's id), and `text` seeds it when it doesn't exist yet. With
    /// `doc`, the entry's name is a template over the bound value instead: `"bind": "@notes",
    /// "doc": "note/{id}"` edits the selected note, and `text` (`"{body}"`) fills from it too.
    /// The text and its undo history are the store's, so a push that drops the editor loses
    /// nothing; the carets and scroll are the editor's, one set per entry it has shown. While it
    /// has focus it takes every key except Tab, Shift-Tab and Esc, so Ctrl-C copies there.
    Editor {
        #[serde(default, skip_serializing_if = "String::is_empty")]
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        doc: Option<String>,
        /// Shown, dimmed, while the text is empty.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        placeholder: Option<String>,
        /// `markdown` styles headings, list markers, quotes and inline code (theme parts
        /// `md.heading`, `md.bullet`, `md.quote`, `md.code`), and task items (`- [ ]`, `- [x]`:
        /// `md.task`, `md.done`): Ctrl-T makes the lines it's on tasks and ticks them (see `tasks`), a click
        /// on a box ticks it. The text stays plain.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        syntax: Option<String>,
        /// Shows the text without changing it: the carets move, select and copy, the wheel and
        /// the keys scroll. A long text or a log to read.
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        readonly: bool,
        /// `indent`: the editor keeps Tab and Shift-Tab, which indent and outdent the lines of the
        /// selection (or a list item; else Tab types two spaces). `indent-lines`: Tab always
        /// indents the lines the caret or the selection is on, as an outliner does. Esc leaves.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tab: Option<String>,
        /// What Ctrl-T does to a ticked task in a Markdown editor: `toggle` (the default) unticks
        /// it; `cycle` makes it plain text again, so text → task → done → text.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tasks: Option<String>,
        /// Where the caret starts the first time the editor shows an entry: `start` (the
        /// default) or `end`. Shown again, an entry keeps its caret.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        caret: Option<String>,
        /// Spans of the text that act on a click: `wiki` (`[[Page]]`), `tag` (`#tag`) or `url`,
        /// each with a `click` and an `s-click` (Shift) action, whose templates read `{$match}`
        /// (the page, the tag, the address). A key reads the link at the caret as `{$link}`.
        /// Links take the theme part `md.link`.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        links: Vec<LinkSpec>,
        /// Ordered lists kept in number, with a marker style per depth for a new level:
        /// `["1.", "a.", "i."]`. After every edit, each list's items are renumbered in its own
        /// style (numbers, letters, roman); Tab and Shift-Tab move an item to the next depth's
        /// style. A `{"list_style": "next"}` key changes one list's style.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        ordered: Vec<String>,
    },
    /// A one-line field (caretline, single-line): an editor whose text never holds a line
    /// break. Enter runs the node's `keys.enter`, so a form submits with a store action.
    Input {
        #[serde(default, skip_serializing_if = "String::is_empty")]
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        placeholder: Option<String>,
        /// `number`: typing that can't make a number is refused, and the node's keys (Enter)
        /// don't run until the text is one.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        accept: Option<String>,
        /// The node's keys (Enter) don't run while the text is blank: a name a form needs.
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        required: bool,
    },
    /// One child at a time, picked by a row of tab titles (click one, or ←/→ when focused). The
    /// titles are templates over the node's bound value (`"Inbox {inbox}"`), and the row can
    /// start with `lead` and end with `trail` (templates too: a name, a date).
    Tabs {
        tabs: Vec<String>,
        children: Vec<Node>,
        /// The tab shown first (default 0), until the person or an action picks another.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        tab: Option<usize>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        lead: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        trail: Option<String>,
    },
    /// Lines drawn in pixels (anti-aliased, a gradient under each) where the terminal draws
    /// images; a braille chart where it doesn't.
    Plot {
        series: Vec<Series>,
        #[serde(default = "yes")]
        fill: bool,
        /// Line width as a fraction of a cell's height.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        width: Option<f32>,
    },
    /// An image file (PNG), scaled into the node.
    Image { src: String },
    /// Vector art: inline SVG markup (`{field}` placeholders filled from the bound value, so it
    /// can draw live data) or an `.svg` file, rendered at the terminal's real pixel size. `alt`
    /// shows where the terminal has no graphics.
    Svg {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        svg: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        src: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        alt: Option<String>,
    },
    /// A lit, glowing dot (the brand mark's `•`): `color`, and `glow` (0 for none).
    Dot {
        color: String,
        #[serde(default)]
        glow: f32,
    },
    /// A world map with a point per bound item at `lat`/`lon` (paths), labelled by `label`.
    Map {
        lat: String,
        lon: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        label: Option<String>,
    },
}

fn yes() -> bool {
    true
}

/// How a list or a tree draws its rows, and which row is which.
///
/// - `item` formats a row (a template over it); with `row_variant` (a path), a row whose value
///   there is a key of `variants` uses that template instead (a section header, a blank), and
///   rows whose variant is in `skip` can't be selected. (`variant`, as on every node, is the
///   node's look from the theme.)
/// - `mark` and `lead` start the selected and the other rows (a list's default `▸ ` and two
///   spaces; a tree's none); `selected` styles the selected row (a style spec; default reverse
///   while focused).
/// - `lines`: every row takes this many lines (the template's lines), the selection all of them.
/// - `keep`: the left side of a row keeps at least this many cells before its right side (after
///   a tab) is cut.
/// - `key` (default `id`): the path that names a row, so the selection stays on it when rows
///   come and go, and a tree's folds stay with it.
/// - `filter`: show only the rows matching the text in this store entry (or bind): every word
///   of it, in any case, somewhere in the row's values.
/// - `empty`: what shows when there are no rows.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Rows {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub item: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub empty: Option<String>,
    #[serde(default, rename = "row_variant", skip_serializing_if = "Option::is_none")]
    pub variant: Option<String>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub variants: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub skip: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mark: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lead: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub selected: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lines: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub keep: Option<u16>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub key: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub filter: Option<String>,
}

